// Import TypeScript types for Express: Request (incoming), Response (outgoing), NextFunction (go to the next step)
import type { NextFunction, Request, Response } from "express";
// Import the Role type (OWNER | ADMIN | AGENT) generated by Prisma from our schema
import type { Role } from "../generated/prisma/enums.js";

// Guard #3: a "middleware factory" = a function that BUILDS a middleware, so each route can say which roles it allows
// Usage example: router.get("/members", requireRole("OWNER", "ADMIN"), controller)
export function requireRole(...allowedRoles: Role[]) {
  // Return the actual middleware; it remembers allowedRoles (this remembering is called a "closure")
  return (_req: Request, res: Response, next: NextFunction) => {
    // requireMembership (guard #2) saved the user's membership here; this guard must run AFTER it
    const membership = res.locals.membership as { role: Role } | undefined;

    // If the role is missing or not in the allowed list, the user may not do this action
    if (!membership || !allowedRoles.includes(membership.role)) {
      // 403 = Forbidden: we know who you are AND that you belong here, but your role is not enough
      // (safe to say 403 here because the user is already a member, so nothing secret is revealed)
      return res.status(403).json({ success: false, message: "You do not have permission to do this" });
    }

    // Role is allowed, so continue to the next step
    next();
  };
}
